17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.Collection;
24	import java.util.List;
25	import java.util.Locale;
26	import java.util.regex.Pattern;
27	
28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
41	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
42	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
73	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
74	
75	    /** Dedicated audit logger; emits an audit line on successful owner create. */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    private final TelephoneNormalizer telephoneNormalizer;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    private final CityRegionResolver cityRegionResolver;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper,
96	                                 TelephoneNormalizer telephoneNormalizer,
97	                                 AddressNormalizer addressNormalizer,
98	                                 CityRegionResolver cityRegionResolver) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	        this.telephoneNormalizer = telephoneNormalizer;
104	        this.addressNormalizer = addressNormalizer;
105	        this.cityRegionResolver = cityRegionResolver;
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
111	        Collection<Owner> owners;
112	        if (lastName != null) {
113	            owners = this.clinicService.findOwnerByLastName(lastName);
114	        } else {
115	            owners = this.clinicService.findAllOwners();
116	        }
117	        if (owners.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
126	        Owner owner = this.clinicService.findOwnerById(ownerId);
127	        if (owner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        HttpHeaders headers = new HttpHeaders();
137	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
138	        if (owner.getRegistrationDate() == null) {
139	            owner.setRegistrationDate(LocalDate.now());
140	        }
141	        // A supplied registration date may not be later than the server's current date.
142	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
143	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
144	        }
145	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
146	        LocalDate registrationDate = owner.getRegistrationDate();
147	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
148	            .map(Owner::getRegistrationDate)
149	            .filter(registrationDate::equals)
150	            .count();
151	        if (ownersCreatedThatDay >= 100) {
152	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
153	        }
154	        String address = addressNormalizer.normalize(owner.getAddress());
155	        if (address.isBlank()) {
156	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
157	        }
158	        owner.setAddress(address);
159	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
160	        if (telephone == null) {
161	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
162	        }
163	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
164	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
165	        }
166	        owner.setTelephone(telephone);
167	        String email = owner.getEmail();
168	        if (email != null) {
169	            email = email.trim();
170	            if (!EMAIL_PATTERN.matcher(email).matches()) {
171	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
172	            }
173	            owner.setEmail(email.toLowerCase(Locale.ROOT));
174	        }
175	        // A postcode is optional, but when supplied it must be four digits and valid for the
176	        // owner's city per the fixed region table; a city with no known region accepts any
177	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
178	        String postcode = owner.getPostcode();
179	        if (postcode != null) {
180	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
181	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
182	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
183	            }
184	        }
185	        // The owner's telephone and email are now in their canonical, stored form.
186	        // Establish the household id before the duplicate check so the candidate's whole
187	        // identity key can be compared against the existing owners': only an owner that
188	        // deliberately shares an existing household (same normalized last name and address)
189	        // is assigned that household's shared id; a plain new owner has no household id, so
190	        // its identity key is decided by telephone and email alone.
191	        String lastNameKey = normalizeIdentity(owner.getLastName());
192	        String addressKey = addressNormalizer.normalize(owner.getAddress());
193	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
194	                && householdExists(lastNameKey, addressKey)) {
195	            owner.setHouseholdId(householdId(lastNameKey, addressKey));
196	        }
197	        if (isDuplicateOwner(owner)) {
198	            return new ResponseEntity<>(HttpStatus.CONFLICT);
199	        }
200	        String cityKey = normalizeIdentity(owner.getCity());
201	        long ownersInCity = this.clinicService.findAllOwners().stream()
202	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
203	            .count();
204	        if (ownersInCity >= 50) {
205	            return new ResponseEntity<>(HttpStatus.CONFLICT);
206	        }
207	        owner.setCustomerCode(customerCode(owner));
208	        owner.setNamesakeCount(namesakeCount(owner));
209	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
210	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
211	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
212	        // still share an existing owner's last name and postcode while carrying a different
213	        // telephone. When it does, it is created but flagged as a possible duplicate of that
214	        // existing owner; otherwise the flag is false and no reference is recorded.
215	        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
216	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
217	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
218	        this.clinicService.saveOwner(owner);
219	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
220	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
221	            ownerMapper.membershipLevel(owner));
222	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
223	        headers.setLocation(UriComponentsBuilder.newInstance()
224	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
225	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
226	    }
227	
228	    /**
229	     * Whether {@code candidate} collides with an already-registered owner under the single
230	     * identity rule enforced on create. This is the one point at which a new owner is
231	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
232	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
233	     * email (or an empty string when absent) and the householdId joined by '|'. The
234	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
235	     * the telephone is part of the key, two members of the same household (same householdId)
236	     * with different telephones have different identityKeys and are both allowed.
237	     *
238	     * <p>The candidate arrives with its telephone and email already normalized and its
239	     * household id already derived, and each existing owner is stored in the same canonical
240	     * form, so an identityKey match means the two owners are genuinely the same identity.
241	     *
242	     * @param candidate the fully-normalized owner about to be created
243	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
244	     */
245	    private boolean isDuplicateOwner(Owner candidate) {
246	        String identityKey = OwnerMapper.identityKey(candidate);
247	        return this.clinicService.findAllOwners().stream()
248	            .map(OwnerMapper::identityKey)
249	            .anyMatch(identityKey::equals);
250	    }
251	
252	    /**
253	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
254	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
255	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
256	     * postcode while carrying a different telephone — a likely re-registration of the same
257	     * person under a new number. Both must supply a postcode for a match to be possible; when
258	     * several existing owners qualify the lowest id is returned so the result is deterministic.
259	     *
260	     * @param candidate the fully-normalized owner about to be created
261	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
262	     */
263	    private Integer possibleDuplicateOf(Owner candidate) {
264	        String postcode = candidate.getPostcode();
265	        if (postcode == null) {
266	            return null;
267	        }
268	        String lastNameKey = normalizeIdentity(candidate.getLastName());
269	        return this.clinicService.findAllOwners().stream()
270	            .filter(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
271	                && postcode.equals(existing.getPostcode())
272	                && !postcode.isBlank()
273	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
274	            .map(Owner::getId)
275	            .filter(java.util.Objects::nonNull)
276	            .min(Integer::compareTo)
277	            .orElse(null);
278	    }
279	
280	    /**
281	     * Whether an existing owner already belongs to the household identified by the given
282	     * normalized last name and address, so a new owner flagged {@code sharesHousehold} has a
283	     * household to join.
284	     */
285	    private boolean householdExists(String lastNameKey, String addressKey) {
286	        return this.clinicService.findAllOwners().stream()
287	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
288	                && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
289	    }
290	
291	    /**
292	     * Normalize a value for household-identity comparison: null becomes an empty
293	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
294	     * to a single space, and the result is lower-cased.
295	     */
296	    private static String normalizeIdentity(String value) {
297	        if (value == null) {
298	            return "";
299	        }
300	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
301	    }
302	
303	    /**
304	     * Build the stable, shared household identifier for an owner, formatted
305	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
306	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
307	     * Owners in the same household (same normalized lastName and address) therefore
308	     * derive an identical householdId.
309	     */
310	    private static String householdId(String lastNameKey, String addressKey) {
311	        return "HH-" + sha256HexPrefix(lastNameKey + "|" + addressKey, 12);
312	    }
313	
314	    /**
315	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
316	     * bytes of {@code source}. This is the single place the SHA-256 hex derivation lives, so
317	     * every identity value built from a truncated hex digest reads the same computation.
318	     */
319	    private static String sha256HexPrefix(String source, int length) {
320	        try {
321	            byte[] digest = MessageDigest.getInstance("SHA-256")
322	                .digest(source.getBytes(StandardCharsets.UTF_8));
323	            StringBuilder sb = new StringBuilder(digest.length * 2);
324	            for (byte b : digest) {
325	                sb.append(String.format("%02x", b));
326	            }
327	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
328	        }
329	        catch (NoSuchAlgorithmException e) {
330	            throw new IllegalStateException("SHA-256 not available", e);
331	        }
332	    }
333	
334	    /**
335	     * Build the customer code assigned to {@code owner} on create, formatted
336	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
337	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
338	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
339	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
340	     */
341	    private String customerCode(Owner owner) {
342	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
343	        String hash8 = sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
344	        return region + "-" + hash8;
345	    }
346	
347	    /**
348	     * The number of existing owners that share {@code owner}'s firstName and lastName,
349	     * compared case-insensitively. The candidate is not yet stored at the point this is
350	     * assigned, so it does not count itself. This is the value stored as the owner's
351	     * namesakeCount on create.
352	     */
353	    private int namesakeCount(Owner owner) {
354	        return (int) this.clinicService.findAllOwners().stream()
355	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
356	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
357	            .count();
358	    }
359	
360	    /**
361	     * Roll a registration date forward to the next business day: a Saturday or Sunday
362	     * advances to the following Monday, and a weekday is returned unchanged.
363	     */
364	    private static LocalDate toBusinessDay(LocalDate date) {
365	        return switch (date.getDayOfWeek()) {
366	            case SATURDAY -> date.plusDays(2);
367	            case SUNDAY -> date.plusDays(1);
368	            default -> date;
369	        };
370	    }
371	
372	    /**
373	     * Build the membership number assigned on create, formatted
374	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
375	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
376	     */
377	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
378	        String yy = String.format("%02d", registrationDate.getYear() % 100);
379	        return customerCode + "-M" + yy;
380	    }
381	
382	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
383	    @Override
384	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
385	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
386	        if (currentOwner == null) {
387	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
388	        }
389	        currentOwner.setAddress(ownerFieldsDto.getAddress());
390	        currentOwner.setCity(ownerFieldsDto.getCity());
391	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
392	        currentOwner.setLastName(ownerFieldsDto.getLastName());
393	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
394	        this.clinicService.saveOwner(currentOwner);
395	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
396	    }
397	
398	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
399	    @Transactional
400	    @Override
401	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
402	        Owner owner = this.clinicService.findOwnerById(ownerId);
403	        if (owner == null) {
404	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
405	        }
406	        this.clinicService.deleteOwner(owner);
407	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
408	    }
409	
410	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
411	    @Override
412	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
413	        Owner owner = this.clinicService.findOwnerById(ownerId);
414	        if (owner == null) {
415	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
416	        }
417	        HttpHeaders headers = new HttpHeaders();
418	        Pet pet = petMapper.toPet(petFieldsDto);
419	        owner.setId(ownerId);
420	        pet.setOwner(owner);
421	        pet.getType().setName(null);
422	        this.clinicService.savePet(pet);
423	        PetDto petDto = petMapper.toPetDto(pet);
424	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
425	            .buildAndExpand(pet.getId()).toUri());
426	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
427	    }
428	
429	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
430	    @Override
431	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
432	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
433	        if (currentOwner != null) {
434	            Pet currentPet = this.clinicService.findPetById(petId);
435	            if (currentPet != null) {
436	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
437	                currentPet.setName(petFieldsDto.getName());
438	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
439	                this.clinicService.savePet(currentPet);
440	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
441	            }
442	        }
443	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
444	    }
445	
446	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
447	    @Override
448	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
449	        HttpHeaders headers = new HttpHeaders();
450	        Visit visit = visitMapper.toVisit(visitFieldsDto);
451	        Pet pet = new Pet();
452	        pet.setId(petId);
453	        visit.setPet(pet);
454	        this.clinicService.saveVisit(visit);
455	        VisitDto visitDto = visitMapper.toVisitDto(visit);
456	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
457	            .buildAndExpand(visit.getId()).toUri());
458	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
459	    }
460	
461	
462	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
463	    @Override
464	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
465	        Owner owner = this.clinicService.findOwnerById(ownerId);
466	        if (owner != null) {
467	            Pet pet = owner.getPet(petId);
468	            if (pet != null) {
469	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
470	            }
471	        }
472	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
473	    }
474	}
