18	
19	import java.util.Map;
20	
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Resolves an owner's city to its canonical region using a single fixed table.
25	 *
26	 * <p>Keeping this in one place means every rule that is keyed by an owner's region reads
27	 * the same city-to-region mapping, so they can never drift apart: the region a city
28	 * derives here is the region every region-keyed rule sees for that city.
29	 *
30	 * <p>A city not listed in the table has no known region and resolves to
31	 * {@link #UNKNOWN_REGION}.
32	 */
33	@Component
34	public class CityRegionResolver {
35	
36	    /** The region returned for a city that is not in the fixed {@link #CITY_REGION} table. */
37	    public static final String UNKNOWN_REGION = "UNKNOWN";
38	
39	    /** Fixed city-to-region table; a city not listed here has no known region. */
40	    private static final Map<String, String> CITY_REGION = Map.of(
41	        "Sydney", "NSW",
42	        "Melbourne", "VIC",
43	        "Brisbane", "QLD");
44	
45	    /** Fixed region-to-postcode range table (inclusive 4-digit low/high), keyed by region; a
46	     *  region not listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode. */
47	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
48	        "NSW", new int[] {2000, 2099},
49	        "VIC", new int[] {3000, 3099},
50	        "QLD", new int[] {4000, 4099});
51	
52	    /**
53	     * Resolve a city to its canonical region.
54	     *
55	     * @param city the owner's city, as stored
56	     * @return the region the city belongs to, or {@link #UNKNOWN_REGION} when the city is
57	     *         not in the fixed table
58	     */
59	    public String regionFor(String city) {
60	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
61	    }
62	
63	    /**
64	     * Resolve a region preferring the postcode over the city. The {@code postcode} is looked up
