34	    @Mapping(target = "displayName",
35	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
36	    @Mapping(target = "initials", expression = "java(initials(owner))")
37	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
38	    @Mapping(target = "locality", expression = "java(locality(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
40	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
41	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
42	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
43	    public abstract OwnerDto toOwnerDto(Owner owner);
44	
45	    /**
46	     * The owner's age band derived from {@code birthDate} relative to the
47	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
48	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
49	     * absent so no band can be computed.
50	     */
51	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
52	        LocalDate birthDate = owner.getBirthDate();
53	        LocalDate registrationDate = owner.getRegistrationDate();
54	        if (birthDate == null || registrationDate == null) {
55	            return null;
56	        }
57	        int age = Period.between(birthDate, registrationDate).getYears();
58	        if (age < 18) {
59	            return OwnerDto.AgeBandEnum.MINOR;
60	        }
61	        if (age < 65) {
62	            return OwnerDto.AgeBandEnum.ADULT;
63	        }
64	        return OwnerDto.AgeBandEnum.SENIOR;
65	    }
66	
67	    /**
68	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
69	     * contained in the customerCode, or null when no customerCode has been assigned.
70	     */
71	    Integer checkDigit(Owner owner) {
72	        String customerCode = owner.getCustomerCode();
73	        return customerCode == null ? null : luhn(customerCode);
74	    }
75	
76	    /**
77	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
78	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
79	     * reduced by 9, and the check digit makes the total a multiple of ten.
80	     */
81	    static int luhn(String s) {
82	        int sum = 0;
83	        boolean doubling = true;
84	        for (int i = s.length() - 1; i >= 0; i--) {
85	            char c = s.charAt(i);
86	            if (c < '0' || c > '9') {
87	                continue;
88	            }
89	            int d = c - '0';
90	            if (doubling) {
91	                d *= 2;
92	                if (d > 9) {
93	                    d -= 9;
94	                }
95	            }
96	            sum += d;
97	            doubling = !doubling;
98	        }
99	        return (10 - (sum % 10)) % 10;
100	    }
101	
102	    /**
103	     * The owner's derived identity key: the normalized telephone, the email (or an empty
104	     * string when absent) and the householdId joined by '|'. This single key is the sole
105	     * basis for duplicate detection on create — two owners are duplicates only when their
106	     * whole identityKey matches, so members of one household with different telephones
107	     * (and hence different keys) are all permitted.
108	     */
109	    public static String identityKey(Owner owner) {
110	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
111	        String email = owner.getEmail() == null ? "" : owner.getEmail();
112	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
113	        return telephone + "|" + email + "|" + householdId;
114	    }
115	
116	    /**
117	     * The owner's preferred contact channel: 'EMAIL' when an email address is
118	     * present, otherwise 'PHONE'.
119	     */
120	    String contactPreference(Owner owner) {
121	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
122	        return hasEmail ? "EMAIL" : "PHONE";
123	    }
124	
125	    /**
126	     * The owner's locality: the REGION component of the customerCode identity (the part before
127	     * the first '-' of {@code '<REGION>-<HASH8>'}). When no customerCode has been assigned this
128	     * falls back to the canonical region derived from the owner via {@link CityRegionResolver},
129	     * preferring the postcode over the city, or 'UNKNOWN' when neither yields a known region.
130	     */
131	    String locality(Owner owner) {
132	        String customerCode = owner.getCustomerCode();
133	        if (customerCode != null) {
134	            int dash = customerCode.indexOf('-');
135	            if (dash >= 0) {
136	                return customerCode.substring(0, dash);
137	            }
138	        }
139	        return cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
140	    }
141	
142	    /**
143	     * The owner's numeric membership level from 1 to 3: starting at 1, plus 1 when an
144	     * email address is present, plus 1 when namesakeCount is 0, capped at 3 (level 4 is
145	     * reserved for tenure).
146	     */
147	    public int membershipLevel(Owner owner) {
148	        int level = 1;
149	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
150	        if (hasEmail) {
151	            level++;
152	        }
153	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
154	        if (uniqueName) {
155	            level++;
156	        }
157	        return Math.min(level, 3);
158	    }
159	
160	    /**
161	     * The upper-cased first letters of firstName and lastName, dot-separated with a
162	     * trailing dot, e.g. 'J.S.'.
163	     */
164	    String initials(Owner owner) {
165	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
166	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
167	    }
