180	        OwnerPageDto ownerPageDto = new OwnerPageDto();
181	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
182	        ownerPageDto.setPage(ownerPage.getNumber());
183	        ownerPageDto.setSize(ownerPage.getSize());
184	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
185	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
186	        return ownerPageDto;
187	    }
188	}
